import sys


def main():
    lines = [line.split() for line in sys.stdin if line.strip()]
    if len(lines) == 1:
        print("ERROR")
        return

    amount_line = lines[0]
    if not amount_line:
        print("ERROR")
        return

    try:
        amount = float(amount_line[0])
    except ValueError:
        print("ERROR")
        return

    people = []
    for line in lines[1:]:
        if len(line) != 2:
            print("ERROR")
            return
        name, weight_str = line
        try:
            weight = int(weight_str)
        except ValueError:
            print("ERROR")
            return
        if weight < 0:
            print("ERROR")
            return
        people.append((name, weight))

    if not people:
        print("ERROR")
        return

    total_weight = sum(w for _, w in people)

    if total_weight == 0:
        print("ERROR")
        return

    # Compute exact shares and fractional parts
    exact_shares = []
    for name, w in people:
        exact_shares.append((name, amount * w / total_weight))

    # Round down to whole cents
    integer_shares = [(name, int(share * 100)) for name, share in exact_shares]

    # Calculate remaining cents
    remaining = int(abs(amount * 100)) - sum(w for _, w in integer_shares)

    # Sort by fractional part descending, then by input order ascending
    sorted_exact = sorted(exact_shares, key=lambda x: (-x[1] % 1, people.index(x)))

    extra = []
    for name, _ in sorted_exact:
        if remaining <= 0:
            break
        extra.append(name)
        remaining -= 1

    # Build final shares
    final_shares = []
    for name, w in integer_shares:
        final_shares.append((name, w / 100.0))

    for name in extra:
        # Find the person with this name
        for i, (n, _) in enumerate(final_shares):
            if n == name:
                final_shares[i] = (name, final_shares[i][1] + 0.01)

    # Apply negative amount if needed
    if amount < 0:
        for name, share in final_shares:
            final_shares[final_shares.index((name, share))] = (name, -share)

    # Output
    for name, share in final_shares:
        print(f"{name} {share:.2f}")


if __name__ == "__main__":
    main()
